import type { MenuContentProps } from "../menu.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { useMenu } from "../hooks/use-menu";
import { MenuClasses } from "../menu.styles";

import { MenuGroup } from "./menu-group";

const MenuContent = forwardRef<HTMLDivElement, MenuContentProps>(
  ({ children, className, isOpening, onCloseAutoFocus, ...props }, ref) => {
    const { dismissible, loop, side, sideOffset, align, alignOffset, RadixComponent } = useMenu();

    const sharedProps = {
      ref,
      onCloseAutoFocus,
      "data-state": isOpening ? "opening" : undefined,
      align,
      alignOffset,
      className: clsx(MenuClasses.content, className),
      loop,
      side,
      sideOffset,
      onEscapeKeyDown: (e: KeyboardEvent) => {
        if (dismissible) return;
        e.preventDefault();
      },
      onInteractOutside: (e: CustomEvent) => {
        if (dismissible) return;
        e.preventDefault();
      },
      onPointerDownOutside: (e: CustomEvent) => {
        if (dismissible) return;
        e.preventDefault();
      },
      ...props,
    };

    const childrenArray = React.Children.toArray(children);
    const groupedChildren: React.ReactNode[] = [];
    let currentGroup: React.ReactNode[] = [];

    const isGroup = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName === MenuGroup.displayName;

    const isDivider = (child: React.ReactNode) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string })?.displayName?.includes("Divider");
    const flushGroup = () => {
      if (currentGroup.length > 0) {
        groupedChildren.push(<MenuGroup key={groupedChildren.length}>{currentGroup}</MenuGroup>);
        currentGroup = [];
      }
    };

    childrenArray.forEach((child) => {
      if (isGroup(child) || isDivider(child)) {
        flushGroup();
        groupedChildren.push(child);
      } else {
        currentGroup.push(child);
      }
    });

    flushGroup();

    return <RadixComponent.Content {...sharedProps}>{groupedChildren}</RadixComponent.Content>;
  },
);
MenuContent.displayName = "Menu.Content";

export { MenuContent };
